import unittest

from infrastructure.postgresql import (
    normalise_postgresql_url,
    translate_sql,
)


class PostgreSQLTranslationTests(unittest.TestCase):
    def test_schema_identity_and_discord_ids_use_bigint(self):
        translated = translate_sql(
            """CREATE TABLE requests (
                   id INTEGER PRIMARY KEY AUTOINCREMENT,
                   user_id INTEGER NOT NULL
               )""",
            include_returning=False,
        )
        self.assertIn(
            "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
            translated,
        )
        self.assertIn("user_id BIGINT NOT NULL", translated)
        self.assertNotIn("AUTOINCREMENT", translated)

    def test_insert_or_ignore_uses_postgresql_conflict_clause(self):
        translated = translate_sql(
            "INSERT OR IGNORE INTO counters (type, count) VALUES (?, 0)"
        )
        self.assertEqual(
            translated,
            "INSERT INTO counters (type, count) VALUES (%s, 0) "
            "ON CONFLICT DO NOTHING",
        )

    def test_identity_insert_returns_generated_id(self):
        translated = translate_sql(
            "INSERT INTO cars (name, plate) VALUES (?, ?)"
        )
        self.assertEqual(
            translated,
            "INSERT INTO cars (name, plate) VALUES (%s, %s) RETURNING id",
        )

    def test_question_mark_inside_literal_is_not_a_parameter(self):
        translated = translate_sql(
            "SELECT '?' AS literal, value FROM settings WHERE key = ?"
        )
        self.assertEqual(
            translated,
            "SELECT '?' AS literal, value FROM settings WHERE key = %s",
        )

    def test_scalar_max_and_nocase_ordering_are_portable(self):
        translated = translate_sql(
            """UPDATE birthday_fundraisers
                  SET total_amount = MAX(0, total_amount - ?);
               ORDER BY cars.name COLLATE NOCASE""",
            include_returning=False,
        )
        self.assertIn("GREATEST(0, total_amount - %s)", translated)
        self.assertIn("ORDER BY LOWER(cars.name)", translated)

    def test_multiline_scalar_extrema_are_not_treated_as_aggregates(self):
        translated = translate_sql(
            """UPDATE game_server_daily_online SET
                   peak_players = MAX(
                       game_server_daily_online.peak_players,
                       excluded.peak_players
                   ),
                   minimum_players = MIN(
                       game_server_daily_online.minimum_players,
                       excluded.minimum_players
                   )
               WHERE server_key = ?
               RETURNING MAX(sample_count)""",
            include_returning=False,
        )
        self.assertIn("peak_players = GREATEST(", translated)
        self.assertIn("minimum_players = LEAST(", translated)
        self.assertIn("RETURNING MAX(sample_count)", translated)

    def test_numeric_case_flag_is_a_boolean_expression(self):
        translated = translate_sql(
            """UPDATE coin_activity_state
                  SET last_message_reward_at = CASE
                      WHEN ? = 1 THEN ?
                      ELSE last_message_reward_at
                  END
                WHERE guild_id = ?""",
            include_returning=False,
        )
        self.assertIn("WHEN %s = 1 THEN %s", translated)

    def test_upsert_arithmetic_qualifies_target_columns(self):
        translated = translate_sql(
            """INSERT INTO coin_activity_daily
                   (guild_id, day, user_id, source, units_milli)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(guild_id, day, user_id, source) DO UPDATE SET
                   units_milli =
                       coin_activity_daily.units_milli + excluded.units_milli""",
            include_returning=False,
        )
        self.assertIn(
            "coin_activity_daily.units_milli + excluded.units_milli",
            translated,
        )

    def test_composite_key_tables_do_not_get_returning_id(self):
        # F13: these tables have composite PKs and must not be in _IDENTITY_TABLES.
        for table in (
            "permission_grants",
            "contract_run_participants",
            "contract_report_shares",
        ):
            translated = translate_sql(
                f"INSERT INTO {table} (a, b) VALUES (?, ?)"
            )
            self.assertEqual(
                translated,
                f"INSERT INTO {table} (a, b) VALUES (%s, %s)",
                msg=table,
            )
            self.assertNotIn("RETURNING", translated.upper())

    def test_sqlalchemy_style_url_is_accepted_by_psycopg(self):
        self.assertEqual(
            normalise_postgresql_url(
                "postgresql+psycopg://user:pass@localhost/database"
            ),
            "postgresql://user:pass@localhost/database",
        )


if __name__ == "__main__":
    unittest.main()
